const DEFAULT_LIGHT_TRANSITION_MS = 400;
const LIVE2D_RUNTIME_READY_CHANNEL = 'live2d_runtime_ready';

type FlutterPointerEventType = 'start' | 'move' | 'end' | 'cancel';

type FlutterPointerEventPayload = {
  type: FlutterPointerEventType;
  x: number;
  y: number;
  viewportWidth?: number;
  viewportHeight?: number;
};

type PointerCoordinateSnapshot = {
  canvasX: number;
  canvasY: number;
  pageX: number;
  pageY: number;
};

function notifyFlutterRuntimeReady(payload: Record<string, unknown> = {}): void {
  try {
    const bridge = (window as any)[LIVE2D_RUNTIME_READY_CHANNEL];
    if (!bridge || typeof bridge.postMessage !== 'function') {
      console.log('[Live2D] Runtime ready channel not available');
      return;
    }

    bridge.postMessage(
      JSON.stringify({
        type: 'runtime-ready',
        timestamp: Date.now(),
        ...payload
      })
    );
    console.log('[Live2D] Sent runtime ready signal to Flutter');
  } catch (error) {
    console.error('[Live2D] Failed to send runtime ready signal:', error);
  }
}

/**
 * ブラウザロード後の処理
 */
window.addEventListener(
  'load',
  (): void => {
    // Initialize WebGL and create the application instance
    if (
      !LAppGlManager.getInstance() ||
      !LAppDelegate.getInstance().initialize()
    ) {
      return;
    }

    LAppDelegate.getInstance().run();
    setupControlPanel();

    // Expose LAppLive2DManager for model readiness checks from Flutter
    window.LAppLive2DManager = LAppLive2DManager;
    notifyFlutterRuntimeReady({ status: 'initialized' });
  },
  { passive: true }
);

/**
 * 終了時の処理
 */
window.addEventListener(
  'beforeunload',
  (): void => LAppDelegate.releaseInstance(),
  { passive: true }
);

