window.setPendingWardrobeExpressions = (snapshot) => {
  if (!snapshot || typeof snapshot !== 'object') {
    (window as any).__Live2DPendingWardrobeExpressions = null;
    console.log('[Live2D] Cleared pending wardrobe expressions');
    return;
  }

  const normalized: Record<string, string[]> = {};

  for (const [channel, value] of Object.entries(snapshot)) {
    let expressions: string[] = [];
    if (Array.isArray(value)) {
      expressions = value
        .map((expr) => (typeof expr === 'string' ? expr.trim() : ''))
        .filter((expr) => expr.length > 0);
    } else if (typeof value === 'string') {
      expressions = value
        .split('+')
        .map((expr) => expr.trim())
        .filter((expr) => expr.length > 0);
    }

    if (expressions.length > 0) {
      normalized[channel] = expressions;
    }
  }

  const channelCount = Object.keys(normalized).length;
  (window as any).__Live2DPendingWardrobeExpressions =
    channelCount > 0 ? normalized : null;

  if (channelCount > 0) {
    console.log(
      `[Live2D] Registered pending wardrobe expressions for ${channelCount} channel${channelCount === 1 ? '' : 's'}`
    );
  } else {
    console.log('[Live2D] No valid wardrobe expressions supplied; clearing pending cache');
  }
};

window.setPendingWardrobeExpressionPaths = (snapshot) => {
  if (!snapshot || typeof snapshot !== 'object') {
    (window as any).__Live2DPendingWardrobeExpressionPaths = null;
    console.log('[Live2D] Cleared pending wardrobe expression paths');
    return;
  }

  const normalized: Record<string, string> = {};

  for (const [expressionName, expressionPath] of Object.entries(snapshot)) {
    if (typeof expressionName !== 'string' || typeof expressionPath !== 'string') {
      continue;
    }

    const normalizedName = expressionName.trim();
    const normalizedPath = expressionPath.trim();
    if (!normalizedName || !normalizedPath) {
      continue;
    }

    normalized[normalizedName] = normalizedPath;
  }

  const expressionCount = Object.keys(normalized).length;
  (window as any).__Live2DPendingWardrobeExpressionPaths =
    expressionCount > 0 ? normalized : null;

  if (expressionCount > 0) {
    console.log(
      `[Live2D] Registered pending wardrobe expression paths for ${expressionCount} expression${expressionCount === 1 ? '' : 's'}`
    );
  } else {
    console.log('[Live2D] No valid wardrobe expression paths supplied; clearing pending cache');
  }
};

