// Apply wardrobe texture changes at runtime: loads newly required, unloads stale
window.setWardrobeTextures = (required: string[], owned: string[], i: number = 0) => {
  const models = LAppLive2DManager.getInstance().getActiveModels();
  if (models.length === 0) {
    console.error('[Live2D] Model not loaded yet, cannot set wardrobe textures');
    return;
  }
  console.log(
    `[Live2D] setWardrobeTextures called for ${models.length} sub-model(s): ` +
    `required=${required.join(', ') || '(none)'}; owned=${owned.join(', ') || '(none)'}`
  );
  for (const model of models) model.applyWardrobeTextures(required, owned);
};

/**
 * Batch wardrobe apply: loads missing expressions in parallel, applies all
 * channels in one shot, and handles texture swaps. Replaces 30+ individual
 * Dart→JS roundtrips with a single call.
 */
window.applyWardrobeBatch = async (jsonStr: string): Promise<string> => {
  try {
    const data = typeof jsonStr === 'string' ? JSON.parse(jsonStr) : jsonStr;
    const models = LAppLive2DManager.getInstance().getActiveModels();
    if (models.length === 0) return JSON.stringify({ error: 'no model' });

    // Texture management is now fully manifest-driven inside
    // _syncWardrobeTextures (called by loadAndApplyWardrobeBatch).
    // Dart texture data (data.textures) is intentionally ignored because
    // it may include base face/body textures that should never be blanked.

    // Apply batch to all sub-models, merge results
    const results = await Promise.all(
      models.map(m => m.loadAndApplyWardrobeBatch(
        data.channels || {},
        data.paths || {}
      ))
    );
    // Return the first result (they should be similar)
    return JSON.stringify(results[0] ?? {});
  } catch (e) {
    return JSON.stringify({ error: String(e) });
  }
};

