// ─── Canvas visibility gate ───────────────────────────────────────────
// Primary anti-nude mechanism: CSS-level opacity controlled exclusively by Dart.
// The canvas is hidden whenever a model changes and only revealed after Dart
// confirms that ALL wardrobe textures + expressions are fully applied.
// Even if the WebGL render loop draws nude frames, they are invisible.
window.hideLive2DCanvas = () => {
  const c = document.querySelector('canvas');
  if (c) (c as HTMLElement).style.opacity = '0';
  console.log('[Live2D] Canvas hidden (Dart-controlled)');
};

window.revealLive2DCanvas = () => {
  // Resume rendering if paused so the correctly-dressed model can draw
  const delegate = LAppDelegate.getInstance();
  if (delegate && delegate.isRenderingPaused()) {
    delegate.resumeRendering();
  }
  // Wait two frames so the correctly-dressed model renders before revealing
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      const c = document.querySelector('canvas');
      if (c) (c as HTMLElement).style.opacity = '1';
      console.log('[Live2D] Canvas revealed (Dart-controlled)');
    });
  });
};

window.isWardrobeSwapComplete = () => {
  const manager = LAppLive2DManager.getInstance();
  if (!manager) return true;
  // All sub-models must have completed their texture swaps
  const models = manager.getActiveModels();
  return models.length === 0 || models.every(m => !m.isTextureSwapActive);
};

window.setCameraMode = (modeId: number): boolean => {
  const preset = CAMERA_MODE_PRESETS[modeId] ?? CAMERA_MODE_PRESETS[0];
  const delegate = LAppDelegate.getInstance();

  if (!delegate) {
    console.error('[Live2D] LAppDelegate not initialized, cannot set camera');
    return false;
  }

  const view = delegate.getView();
  if (!view || typeof view.setCameraPreset !== 'function') {
    console.error('[Live2D] LAppView not ready, cannot set camera');
    return false;
  }

  view.setCameraPreset(preset.scale, preset.duration);
  const manager = LAppLive2DManager.getInstance();
  if (manager && typeof manager.setModelYOffset === 'function') {
    const targetOffset =
      preset.modelYOffset ?? LAppDefine.ModelInitialYOffset ?? 0;
    const offsetDuration =
      preset.modelYOffsetDuration ?? preset.duration ?? 0;
    manager.setModelYOffset(targetOffset, offsetDuration);
  }
  if (manager && typeof manager.setModelXOffset === 'function') {
    const targetXOffset = preset.modelXOffset ?? 0;
    const xOffsetDuration = preset.modelXOffsetDuration ?? preset.duration ?? 0;
    manager.setModelXOffset(targetXOffset, xOffsetDuration);
  }
  return true;
};

