const VALID_POINTER_EVENT_TYPES: ReadonlySet<FlutterPointerEventType> = new Set([
  'start',
  'move',
  'end',
  'cancel'
]);

const toNumber = (value: unknown, fallback = 0): number => {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const getCanvasElement = (): HTMLCanvasElement | null => {
  return document.querySelector('canvas');
};

const computePointerCoordinates = (
  payload: FlutterPointerEventPayload,
  canvas: HTMLCanvasElement
): PointerCoordinateSnapshot => {
  const rect = canvas.getBoundingClientRect();
  const viewportWidth = toNumber(
    payload.viewportWidth,
    window.innerWidth || rect.width || canvas.clientWidth || 1
  );
  const viewportHeight = toNumber(
    payload.viewportHeight,
    window.innerHeight || rect.height || canvas.clientHeight || 1
  );
  const normalizedX = viewportWidth > 0 ? toNumber(payload.x) / viewportWidth : 0;
  const normalizedY = viewportHeight > 0 ? toNumber(payload.y) / viewportHeight : 0;
  const canvasWidth = rect.width || canvas.clientWidth || 1;
  const canvasHeight = rect.height || canvas.clientHeight || 1;
  const canvasX = normalizedX * canvasWidth;
  const canvasY = normalizedY * canvasHeight;
  const scrollX = window.scrollX || window.pageXOffset || 0;
  const scrollY = window.scrollY || window.pageYOffset || 0;

  return {
    canvasX,
    canvasY,
    pageX: rect.left + scrollX + canvasX,
    pageY: rect.top + scrollY + canvasY
  };
};

const forwardPointerToLive2D = (
  eventType: FlutterPointerEventType,
  coords: PointerCoordinateSnapshot
): boolean => {
  const delegate = LAppDelegate.getInstance();
  if (!delegate || typeof delegate.getView !== 'function') {
    return false;
  }

  const view = delegate.getView();
  if (!view) {
    return false;
  }

  const delegateState = delegate as LAppDelegate & { _captured?: boolean };

  if (eventType === 'start') {
    delegateState._captured = true;
    view.onTouchesBegan(coords.canvasX, coords.canvasY);
    return true;
  }

  if (!delegateState._captured) {
    return false;
  }

  if (eventType === 'move') {
    view.onTouchesMoved(coords.canvasX, coords.canvasY);
    return true;
  }

  if (eventType === 'end' || eventType === 'cancel') {
    delegateState._captured = false;
    view.onTouchesEnded(coords.canvasX, coords.canvasY);
    return true;
  }

  return false;
};

window.forwardFlutterTouchEvent = (
  payload: string | FlutterPointerEventPayload
): boolean => {
  try {
    if (!payload) {
      return false;
    }

    const data: Partial<FlutterPointerEventPayload> =
      typeof payload === 'string' ? JSON.parse(payload) : payload;

    if (!data || typeof data !== 'object') {
      return false;
    }

    const type = String(data.type ?? '').toLowerCase() as FlutterPointerEventType;
    if (!VALID_POINTER_EVENT_TYPES.has(type)) {
      return false;
    }

    const canvas = getCanvasElement();
    if (!canvas) {
      return false;
    }

    const coords = computePointerCoordinates(
      {
        type,
        x: toNumber(data.x),
        y: toNumber(data.y),
        viewportWidth: data.viewportWidth,
        viewportHeight: data.viewportHeight
      },
      canvas
    );

    return forwardPointerToLive2D(type, coords);
  } catch (error) {
    console.warn('[Live2D] forwardFlutterTouchEvent failed', error);
    return false;
  }
};

