/**
 * Start a motion with flexible parameters:
 * - playMotion(fileName, modelIndex?) - e.g., playMotion("Idle_00", 0) or playMotion("Idle_00.motion3.json")
 * - playMotion(motionName, motionId, modelIndex?) - e.g., playMotion("Idle", 0, 0)
 */
window.playMotion = (motionNameOrFile: string, motionIdOrModelIndex?: number, modelIndex?: number) => {
  const manager = LAppLive2DManager.getInstance();
  const models = manager.getActiveModels();
  if (models.length === 0) {
    console.error('Model not loaded yet - cannot play motion');
    return;
  }

  // Use the first sub-model to resolve the motion name/id
  const primaryModel = models[0];
  let motionName: string;
  let motionId: number;

  if (modelIndex !== undefined) {
    // Old way: playMotion(motionName, motionId, modelIndex)
    motionName = motionNameOrFile;
    motionId = motionIdOrModelIndex!;
  } else if (motionIdOrModelIndex !== undefined && typeof motionIdOrModelIndex === 'number') {
    if (primaryModel._modelSetting) {
      const motionInfo = primaryModel.findMotionByFileName(motionNameOrFile);
      if (motionInfo) {
        motionName = motionInfo.group;
        motionId = motionInfo.index;
      } else {
        // Treat as old way: playMotion(motionName, motionId)
        motionName = motionNameOrFile;
        motionId = motionIdOrModelIndex;
      }
    } else {
      motionName = motionNameOrFile;
      motionId = motionIdOrModelIndex;
    }
  } else {
    // New way: playMotion(fileName)
    if (!primaryModel._modelSetting) {
      console.error('Model not loaded yet - cannot play motion');
      return;
    }
    const motionInfo = primaryModel.findMotionByFileName(motionNameOrFile);
    if (motionInfo) {
      motionName = motionInfo.group;
      motionId = motionInfo.index;
    } else {
      console.error(`Motion file not found: ${motionNameOrFile}`);
      return;
    }
  }

  // Play motion on ALL sub-models so they animate together
  for (const model of models) {
    if (model._modelSetting) {
      model.playMotion(motionName, motionId, 100);
    }
  }
}

