function setupControlPanel(): void {
  const panel = document.getElementById('control-panel');

  // Create texture status overlay (top-left, admin-only)
  let textureOverlay = document.getElementById('texture-overlay') as HTMLDivElement | null;
  if (!textureOverlay) {
    textureOverlay = document.createElement('div');
    textureOverlay.id = 'texture-overlay';
    Object.assign(textureOverlay.style, {
      position: 'fixed',
      top: '8px',
      left: '8px',
      zIndex: '9999',
      background: 'rgba(0,0,0,0.72)',
      color: '#fff',
      fontFamily: 'monospace',
      fontSize: '11px',
      lineHeight: '1.5',
      padding: '6px 10px',
      borderRadius: '6px',
      pointerEvents: 'none',
      display: 'none',
      whiteSpace: 'pre',
      maxWidth: '260px',
    });
    document.body.appendChild(textureOverlay);
  }

  const expressionContainer = document.getElementById('expression-buttons');
  const motionContainer = document.getElementById('motion-buttons');
  const expressionEmpty = document.getElementById('expression-empty');
  const motionEmpty = document.getElementById('motion-empty');

  if (!panel || !expressionContainer || !motionContainer) {
    return;
  }

  let lastSignature = '';

  const formatLabel = (name: string): string => {
    if (!name) {
      return 'Unknown';
    }
    const lastSegment = name.split(/[\\/]/).pop() ?? name;
    const withoutExtension = lastSegment
      .replace(/\.motion3\.json$/i, '')
      .replace(/\.exp3\.json$/i, '')
      .replace(/\.moc3$/i, '')
      .replace(/\.json$/i, '');
    return withoutExtension.replace(/[_-]+/g, ' ');
  };

  const refreshControls = () => {
    const manager = LAppLive2DManager.getInstance();
    if (!manager) {
      return;
    }

    const model = manager.getModel(0);
    if (!model || !model._modelSetting) {
      return;
    }

    // Texture status overlay — only shown in admin mode
    const isAdmin = panel?.classList.contains('admin-mode') ?? false;
    if (textureOverlay) {
      if (isAdmin && typeof model.getTextureStatus === 'function') {
        const slots = model.getTextureStatus();
        const lines = ['── Textures ──────────────────'];
        for (const s of slots) {
          let icon: string;
          let tag: string;
          if (s.owned) {
            icon = s.loaded ? '🟢' : '⬜';
            tag = s.loaded ? 'loaded' : 'transp';
          } else if (s.manifested) {
            icon = '🟡';
            tag = 'manifest';
          } else {
            icon = '🟦';
            tag = 'base';
          }
          lines.push(`${icon} [${String(s.slot).padStart(2, '0')}] ${s.basename.padEnd(16)} ${tag}`);
        }
        lines.push('─────────────────────────────');
        lines.push('🟦 base  🟡 manifest  🟢 loaded  ⬜ transp');
        textureOverlay.textContent = lines.join('\n');
        textureOverlay.style.display = 'block';
      } else {
        textureOverlay.style.display = 'none';
      }
    }

    // Use dynamically loaded expression names (from manifest subfolder system)
    // falling back to model3.json list if the getter isn't available yet
    const expressions: string[] = typeof model.getLoadedExpressionNames === 'function'
      ? Array.from(model.getLoadedExpressionNames()).sort()
      : (() => {
          const count = typeof model._modelSetting.getExpressionCount === 'function'
            ? model._modelSetting.getExpressionCount() : 0;
          const names: string[] = [];
          for (let i = 0; i < count; i++) names.push(model._modelSetting.getExpressionName(i));
          return names;
        })();

    const motionGroups: { name: string; motions: { index: number; file: string }[] }[] = [];
    const motionGroupCount = typeof model._modelSetting.getMotionGroupCount === 'function'
      ? model._modelSetting.getMotionGroupCount()
      : 0;

    for (let gi = 0; gi < motionGroupCount; gi++) {
      const groupName = model._modelSetting.getMotionGroupName(gi);
      const motionCount = model._modelSetting.getMotionCount(groupName);
      const entries: { index: number; file: string }[] = [];

      for (let mi = 0; mi < motionCount; mi++) {
        const fileName = model._modelSetting.getMotionFileName(groupName, mi);
        entries.push({ index: mi, file: fileName });
      }

      motionGroups.push({ name: groupName, motions: entries });
    }

    const signature = JSON.stringify({
      expressions,
      motions: motionGroups.map((group) => ({
        name: group.name,
        files: group.motions.map((motion) => motion.file),
      })),
    });

    if (signature === lastSignature) {
      return;
    }

    lastSignature = signature;

    expressionContainer.innerHTML = '';
    if (expressions.length === 0) {
      if (expressionEmpty) {
        expressionEmpty.removeAttribute('hidden');
      }
    } else {
      if (expressionEmpty) {
        expressionEmpty.setAttribute('hidden', '');
      }

      expressions.forEach((expressionName) => {
        const button = document.createElement('button');
        button.className = 'control-button';
        button.textContent = formatLabel(expressionName);
        button.title = expressionName;
        button.addEventListener('click', () => {
          // Check if model is still loaded before playing
          const currentModel = LAppLive2DManager.getInstance().getModel(0);
          if (!currentModel || !currentModel._modelSetting) {
            console.error('Model not loaded yet - cannot play expression');
            return;
          }
          window.playExpression(expressionName);
        });
        expressionContainer.appendChild(button);
      });
    }

    motionContainer.innerHTML = '';
    if (motionGroups.length === 0) {
      if (motionEmpty) {
        motionEmpty.removeAttribute('hidden');
      }
      return;
    }

    if (motionEmpty) {
      motionEmpty.setAttribute('hidden', '');
    }

    motionGroups.forEach((group) => {
      const wrapper = document.createElement('div');
      wrapper.className = 'motion-group';

      const heading = document.createElement('div');
      heading.className = 'group-title';
      heading.textContent = group.name;
      wrapper.appendChild(heading);

      const grid = document.createElement('div');
      grid.className = 'button-grid';

      group.motions.forEach(({ index, file }) => {
        const button = document.createElement('button');
        button.className = 'control-button';
        const labelSource = file || `${group.name}_${index}`;
        const label = formatLabel(labelSource) || `${group.name} ${index + 1}`;
        button.textContent = label;
        button.title = labelSource;
        button.addEventListener('click', () => {
          // Check if model is still loaded before playing
          const currentModel = LAppLive2DManager.getInstance().getModel(0);
          if (!currentModel || !currentModel._modelSetting) {
            console.error('Model not loaded yet - cannot play motion');
            return;
          }
          window.playMotion(group.name, index);
        });
        grid.appendChild(button);
      });

      wrapper.appendChild(grid);
      motionContainer.appendChild(wrapper);
    });
  };

  const REFRESH_INTERVAL_MS = 800;
  refreshControls();
  window.setInterval(refreshControls, REFRESH_INTERVAL_MS);

  // --- Texture debug panel (interactive load/unload per slot) ---
  setupTextureDebugPanel();

  // --- SplitAt debug slider (standalone floating overlay) ---
  setupSplitAtOverlay();

  // --- Frame profiler overlay (admin only) ---
  setupProfilingOverlay();
}

/**
 * Interactive texture debug panel inside the control panel.
 * Shows each texture slot with load/unload toggle buttons.
 * Refreshes automatically, preserving interactive state.
 */
function setupTextureDebugPanel(): void {
  const container = document.getElementById('texture-debug-buttons');
  if (!container) return;

  // Track which textures are currently being loaded (async)
  const loadingSet = new Set<string>();
  let lastSlotSig = '';

  const refresh = () => {
    const panel = document.getElementById('control-panel');
    const isAdmin = panel?.classList.contains('admin-mode') ?? false;
    const section = document.getElementById('texture-debug-section');
    if (section) section.style.display = isAdmin ? '' : 'none';
    if (!isAdmin) return;

    const model = LAppLive2DManager.getInstance()?.getModel(0);
    if (!model || typeof model.getTextureStatus !== 'function') {
      container.innerHTML = '<p class="empty-state">No model loaded</p>';
      lastSlotSig = '';
      return;
    }

    const slots = model.getTextureStatus();
    // Only rebuild DOM when the slot list changes; update status inline otherwise
    const sig = slots.map(s => s.basename).join(',');
    if (sig !== lastSlotSig) {
      lastSlotSig = sig;
      container.innerHTML = '';
      for (const s of slots) {
        const row = document.createElement('div');
        row.dataset.basename = s.basename;
        row.style.cssText = 'display:flex;align-items:center;gap:6px;margin-bottom:4px;font-size:12px;font-family:monospace;';

        const statusIcon = document.createElement('span');
        statusIcon.className = 'tex-status-icon';
        statusIcon.style.cssText = 'width:18px;text-align:center;';
        row.appendChild(statusIcon);

        const slotLabel = document.createElement('span');
        slotLabel.style.cssText = 'width:24px;opacity:0.5;';
        slotLabel.textContent = `[${String(s.slot).padStart(2, '0')}]`;
        row.appendChild(slotLabel);

        const nameLabel = document.createElement('span');
        nameLabel.style.cssText = 'flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
        nameLabel.textContent = s.basename;
        nameLabel.title = s.basename;
        row.appendChild(nameLabel);

        const loadBtn = document.createElement('button');
        loadBtn.className = 'control-button tex-load-btn';
        loadBtn.style.cssText = 'padding:2px 8px;font-size:11px;min-width:55px;';
        loadBtn.textContent = 'Load';
        loadBtn.addEventListener('click', async () => {
          loadBtn.disabled = true;
          loadBtn.textContent = '...';
          loadingSet.add(s.basename);
          await window.debugLoadTexture(s.basename);
          loadingSet.delete(s.basename);
          loadBtn.disabled = false;
        });
        row.appendChild(loadBtn);

        const unloadBtn = document.createElement('button');
        unloadBtn.className = 'control-button tex-unload-btn';
        unloadBtn.style.cssText = 'padding:2px 8px;font-size:11px;min-width:55px;';
        unloadBtn.textContent = 'Unload';
        unloadBtn.addEventListener('click', () => {
          window.debugUnloadTexture(s.basename);
        });
        row.appendChild(unloadBtn);

        container.appendChild(row);
      }
    }

    // Update status icons and button states based on current status
    const currentSlots = model.getTextureStatus();
    for (const s of currentSlots) {
      const row = container.querySelector(`[data-basename="${CSS.escape(s.basename)}"]`) as HTMLDivElement | null;
      if (!row) continue;
      const icon = row.querySelector('.tex-status-icon') as HTMLSpanElement;
      if (icon) {
        if (loadingSet.has(s.basename)) {
          icon.textContent = '⏳';
        } else if (s.owned) {
          icon.textContent = s.loaded ? '🟢' : '⬜';
        } else if (s.manifested) {
          icon.textContent = '🟡';
        } else {
          icon.textContent = '🟦';
        }
      }
    }
  };

  window.setInterval(refresh, 600);
  refresh();
}

/**
 * Creates a standalone floating overlay with splitAt sliders.
 * Auto-shows whenever the current model has split render passes.
 * Only visible in admin mode.
 */
function setupSplitAtOverlay(): void {
  // Create the floating container
  const overlay = document.createElement('div');
  overlay.id = 'splitAt-debug-overlay';
  Object.assign(overlay.style, {
    position: 'fixed',
    bottom: '16px',
    left: '16px',
    width: '280px',
    background: 'rgba(0, 0, 0, 0.75)',
    backdropFilter: 'blur(6px)',
    color: '#fff',
    fontFamily: "'Segoe UI', system-ui, sans-serif",
    fontSize: '13px',
    padding: '12px 14px',
    borderRadius: '10px',
    boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
    zIndex: '99999',
    display: 'none',
    userSelect: 'none',
  });
  document.body.appendChild(overlay);

  const title = document.createElement('div');
  title.textContent = 'Split At Debug';
  title.style.cssText = 'font-weight:600;font-size:14px;margin-bottom:10px;opacity:0.9;';
  overlay.appendChild(title);

  const slidersContainer = document.createElement('div');
  slidersContainer.id = 'splitAt-sliders';
  overlay.appendChild(slidersContainer);

  let lastSig = '';

  const refresh = () => {
    const panel = document.getElementById('control-panel');
    const isAdmin = panel?.classList.contains('admin-mode') ?? false;
    if (!isAdmin) {
      overlay.style.display = 'none';
      lastSig = '';
      return;
    }

    const manager = LAppLive2DManager.getInstance();
    if (!manager) {
      overlay.style.display = 'none';
      return;
    }

    const passes = manager.getRenderPasses();
    if (!passes || passes.length === 0) {
      overlay.style.display = 'none';
      lastSig = '';
      return;
    }

    // Find sub-models that have split passes (2 passes per subKey)
    const subKeyCounts = new Map<string, number>();
    for (const p of passes) {
      subKeyCounts.set(p.subKey, (subKeyCounts.get(p.subKey) || 0) + 1);
    }

    const splitSubKeys: string[] = [];
    for (const [key, count] of subKeyCounts) {
      if (count === 2) splitSubKeys.push(key);
    }

    if (splitSubKeys.length === 0) {
      overlay.style.display = 'none';
      lastSig = '';
      return;
    }

    overlay.style.display = '';

    // Rebuild sliders only when sub-model set changes
    const sig = splitSubKeys.join(',');
    if (sig === lastSig) return;
    lastSig = sig;

    slidersContainer.innerHTML = '';

    for (const subKey of splitSubKeys) {
      const drawableCount = manager.getSubModelDrawableCount(subKey);
      const backPass = passes.find(p => p.subKey === subKey && p.minOrder === 0);
      const currentSplitAt = backPass ? backPass.maxOrder : 0;
      const maxVal = drawableCount > 0 ? drawableCount : 3000;

      const wrapper = document.createElement('div');
      wrapper.style.marginBottom = '10px';

      const labelRow = document.createElement('div');
      labelRow.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;';

      const nameLabel = document.createElement('span');
      nameLabel.style.cssText = 'font-size:12px;opacity:0.7;';
      nameLabel.textContent = subKey.split(':').pop() || subKey;

      const valueLabel = document.createElement('span');
      valueLabel.style.cssText = 'font-size:12px;font-family:monospace;color:#4fc3f7;';
      valueLabel.textContent = `${currentSplitAt} / ${maxVal}`;

      labelRow.appendChild(nameLabel);
      labelRow.appendChild(valueLabel);
      wrapper.appendChild(labelRow);

      const slider = document.createElement('input');
      slider.type = 'range';
      slider.min = '0';
      slider.max = String(maxVal);
      slider.value = String(currentSplitAt);
      slider.style.cssText = 'width:100%;accent-color:#4fc3f7;cursor:pointer;';

      slider.addEventListener('input', () => {
        const val = parseInt(slider.value, 10);
        valueLabel.textContent = `${val} / ${maxVal}`;
        manager.setSplitAt(subKey, val);
      });

      wrapper.appendChild(slider);
      slidersContainer.appendChild(wrapper);
    }
  };

  window.setInterval(refresh, 1000);
}

/**
 * Frame-time profiling overlay. Only visible when admin mode is active.
 * Shows update/draw/total ms, FPS, model count, drawable count.
 */
function setupProfilingOverlay(): void {
  const overlay = document.createElement('div');
  overlay.id = 'perf-overlay';
  Object.assign(overlay.style, {
    position: 'fixed',
    top: '16px',
    left: '16px',
    width: '240px',
    background: 'rgba(0, 0, 0, 0.75)',
    backdropFilter: 'blur(6px)',
    color: '#fff',
    fontFamily: "'Courier New', monospace",
    fontSize: '12px',
    padding: '10px 12px',
    borderRadius: '10px',
    boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
    zIndex: '99999',
    display: 'none',
    userSelect: 'none',
    lineHeight: '1.6',
  });
  document.body.appendChild(overlay);

  const title = document.createElement('div');
  title.textContent = '⚡ Frame Profiler';
  title.style.cssText = 'font-weight:700;font-size:13px;margin-bottom:6px;color:#ffb74d;';
  overlay.appendChild(title);

  const stats = document.createElement('pre');
  stats.style.cssText = 'margin:0;white-space:pre;font-size:11px;';
  overlay.appendChild(stats);

  // Rolling averages
  const WINDOW = 60;
  const history: { total: number; update: number; draw: number }[] = [];
  let lastTs = performance.now();
  let frameCount = 0;
  let fps = 0;

  const refresh = () => {
    // Only show when admin mode is on
    const panel = document.getElementById('control-panel');
    const isAdmin = panel?.classList.contains('admin-mode') ?? false;
    if (!isAdmin) {
      overlay.style.display = 'none';
      return;
    }

    const manager = LAppLive2DManager.getInstance();
    if (!manager) {
      overlay.style.display = 'none';
      return;
    }

    overlay.style.display = '';

    const p = manager.lastFrameProfile;
    history.push({ total: p.totalMs, update: p.updateMs, draw: p.drawMs });
    if (history.length > WINDOW) history.shift();

    // Compute averages
    const avg = (fn: (h: typeof history[0]) => number) =>
      history.reduce((s, h) => s + fn(h), 0) / history.length;
    const avgTotal = avg(h => h.total);
    const avgUpdate = avg(h => h.update);
    const avgDraw = avg(h => h.draw);

    // FPS counter
    frameCount++;
    const now = performance.now();
    if (now - lastTs >= 1000) {
      fps = frameCount;
      frameCount = 0;
      lastTs = now;
    }

    const bar = (ms: number, max: number) => {
      const len = Math.round(Math.min(ms / max, 1) * 16);
      const color = ms > 16.67 ? '#ff5252' : ms > 8 ? '#ffb74d' : '#69f0ae';
      return `<span style="color:${color}">${'█'.repeat(len)}${'░'.repeat(16 - len)}</span>`;
    };

    stats.innerHTML = [
      `FPS:       <b style="color:${fps < 30 ? '#ff5252' : fps < 55 ? '#ffb74d' : '#69f0ae'}">${fps}</b>`,
      `Total:     ${avgTotal.toFixed(2)}ms ${bar(avgTotal, 33)}`,
      `  Update:  ${avgUpdate.toFixed(2)}ms ${bar(avgUpdate, 33)}`,
      `  Draw:    ${avgDraw.toFixed(2)}ms ${bar(avgDraw, 33)}`,
      `Models:    ${p.modelCount}`,
      `Passes:    ${p.passCount}`,
      `Drawables: ${p.drawableCount}`,
    ].join('\n');
  };

  // Update at ~30Hz to minimize overlay overhead
  window.setInterval(refresh, 33);
}
