// Global resolution tier for texture loading
let currentResolutionTier: string = 'high';

/**
 * Set the global resolution tier for all Live2D models
 * @param tier Resolution tier: 'low', 'medium', or 'high'
 */
export function setGlobalResolutionTier(tier: string): void {
  currentResolutionTier = tier;
  console.log(`[LAppModel] Global resolution tier set to: ${tier}`);
}

/**
 * Get the current global resolution tier
 * @returns Current resolution tier
 */
export function getGlobalResolutionTier(): string {
  return currentResolutionTier;
}

/**
 * Apply resolution tier to texture path
 * Converts paths like "model.8192/texture.png" to "model.2048/texture.png" based on tier
 * @param texturePath Original texture path from model3.json
 * @param tier Resolution tier: 'low', 'medium', or 'high'
 * @returns Modified texture path with appropriate resolution folder
 */
function applyResolutionTier(texturePath: string, tier: string): string {
  // Match resolution folder patterns like .8192/, .4096/, .2048/, .1024/, .512/
  const resolutionPattern = /\.(\d{3,4})\//;
  const match = texturePath.match(resolutionPattern);

  if (!match) {
    // No resolution folder found, return as-is
    return texturePath;
  }

  const originalRes = parseInt(match[1]);
  let targetRes: number;

  switch (tier) {
    case 'low':
      // Use 512 or 25% of original, whichever is reasonable
      targetRes = Math.max(512, Math.floor(originalRes * 0.25));
      break;
    case 'medium':
      // Use 1024-2048 or 50% of original
      targetRes = Math.max(1024, Math.floor(originalRes * 0.5));
      break;
    case 'high':
    default:
      // Use original resolution
      return texturePath;
  }

  // Round to nearest power of 2 or common texture size
  const commonSizes = [512, 1024, 2048, 4096, 8192];
  targetRes = commonSizes.reduce((prev, curr) =>
    Math.abs(curr - targetRes) < Math.abs(prev - targetRes) ? curr : prev
  );

  // Replace the resolution in the path
  const modifiedPath = texturePath.replace(resolutionPattern, `.${targetRes}/`);

  console.log(`[LAppModel] Texture path resolution: ${tier} tier -> ${originalRes} => ${targetRes}`);
  console.log(`[LAppModel]   Original: ${texturePath}`);
  console.log(`[LAppModel]   Modified: ${modifiedPath}`);

  return modifiedPath;
}

